// Converte "dd/mm/aaaa" em Date; aceita undefined/null
function parseDataBR(dataStr) {
  if (dataStr === undefined || dataStr === null || typeof dataStr !== "string") return null;
  const parts = dataStr.split("/");
  if (parts.length !== 3) return null;
  const [dia, mes, ano] = parts.map(Number);
  return new Date(ano, mes - 1, dia);
}

// Converte Data do registro (ISO ou DD/MM/YYYY) em Date
function toDate(val) {
  if (val == null) return null;
  if (val instanceof Date) return val;
  if (typeof val === "string") {
    if (val.includes("T")) return new Date(val); // ISO
    return parseDataBR(val); // DD/MM/YYYY
  }
  return null;
}

// Nomes corretos da tool gerar_relatorio
const dataInicialStr = $('Tools').item.json.data_inicio;
const dataFinalStr = $('Tools').item.json.data_fim;
const categoriaFiltrada = $('Tools').item.json.Categoria || "Todos";

const dataInicial = parseDataBR(dataInicialStr);
const dataFinal = parseDataBR(dataFinalStr);

if (dataInicial === null || dataFinal === null) {
  return [{ json: { error: "Datas inválidas. Use data_inicio e data_fim no formato DD/MM/YYYY." } }];
}

const dados = $input.first().json.data || [];

let total = 0;
let gastosFiltrados = [];

for (const gasto of dados) {
  const dataGasto = toDate(gasto["Data"]);

  const dentroDoPeriodo = dataGasto && dataGasto >= dataInicial && dataGasto <= dataFinal;
  const categoriaConfere = categoriaFiltrada === "Todos" || gasto["Categoria"] === categoriaFiltrada;

  if (dentroDoPeriodo && categoriaConfere) {
    const valor = parseFloat(String(gasto["Valor"] || 0).replace(",", "."));
    total += valor;
    gastosFiltrados.push(gasto);
  }
}

return [
  {
    json: {
      "Total Filtrado (R$)": total.toFixed(2),
      "Categoria": categoriaFiltrada,
      "Período": `${dataInicialStr} a ${dataFinalStr}`,
      "Registros Encontrados": gastosFiltrados.length,
      "Detalhes": gastosFiltrados
    }
  }
];
